INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("リリ", 125801, 321, 2, 1, 1, 1, 0, 40011, 24001, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("クリア", 126001, 322, 2, 1, 2, 1, 0, 40011, 24001, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("プレシア", 126101, 323, 2, 1, 3, 1, 0, 40011, 24001, "んーと。\nこれ、あげる。\nはい");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("リリ", 125801, 324, 2, 2, 4, 1, 0, 40011, 24001, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("クリア", 126001, 325, 2, 2, 5, 1, 0, 40011, 24001, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("プレシア", 126101, 326, 2, 2, 6, 1, 0, 40011, 24001, "お兄。\nきてくれて、うれしい");
